fragments.new:
var answers = {};            // id -> option index, or array of indices for multi
var demoPrefill = new URLSearchParams(window.location.search).get("prefill") === "demo";
function prefillDemoAnswers(){
  QUESTIONS.forEach(function(q){
    if (q.conditional) return;
    answers[q.id] = q.multi ? [0] : Math.min(1, q.opts.length - 1);
  });
  answers.recognize = [0, 2, 5];
  answers.weird = [0, 1];
  answers.age = 2;
  answers.weirdWorst = 0;
}
if (demoPrefill) prefillDemoAnswers();

fragments.old:
if (q.multi) {
  nb.classList.remove("hidden");
  nb.disabled = !(Array.isArray(answers[q.id]) && answers[q.id].length > 0);
} else nb.classList.add("hidden");

fragments.new:
if (q.multi || demoPrefill) {
  nb.classList.remove("hidden");
  nb.disabled = q.multi
    ? !(Array.isArray(answers[q.id]) && answers[q.id].length > 0)
    : !(typeof answers[q.id] === "number" && q.opts[answers[q.id]]);
} else nb.classList.add("hidden");

clearTimeout(advanceTimer);
if (demoPrefill) { $("nextBtn").disabled = false; return; }
advanceTimer = setTimeout(next, 220);

answers = {}; pos = 0;
if (demoPrefill) prefillDemoAnswers();
order = QUESTIONS.filter(function(q){ return !q.conditional; }).map(function(q){ return q.id; });
